import {parseSave,checksum,PROFILE} from './core.mjs';
import {MON_INDEX} from './mon-index.mjs';
const view=b=>new DataView(b.buffer,b.byteOffset,b.byteLength);
export function readStorage(input){const s=parseSave(input),buffer=new Uint8Array(32976);let offset=0;for(let id=5;id<=13;id++){const n=PROFILE.sizes[id],p=s.active.sections.get(id);buffer.set(s.bytes.subarray(p,p+n),offset);offset+=n;}if(buffer[0]>20)throw Error('รูปแบบกล่อง PC ไม่ตรงกับ ROM ที่รองรับ');return buffer;}
export function capacity(input){const s=parseSave(input),pc=readStorage(input),party=s.bytes[s.world+0x234];if(party>6)throw Error('จำนวน Party ไม่ถูกต้อง');const boxes=[];for(let box=0;box<21;box++){let free=0;for(let slot=0;slot<30;slot++){const p=4+(box*30+slot)*52;if(pc.subarray(p,p+52).every(x=>x===0))free++;}boxes.push({box,free});}return {party,boxes};}
export function addPokemon(input,requests,templates){if(!requests?.length)return new Uint8Array(input).slice();if(!templates||templates.length!==MON_INDEX.filter(m=>!m.unavailable).length*7600)throw Error('ข้อมูลสร้างโปเกมอนยังโหลดไม่ครบ');const s=parseSave(input),out=s.bytes.slice(),v=view(out),storage=readStorage(out);let count=out[s.world+0x234];if(count>6)throw Error('จำนวน Party ไม่ถูกต้อง');let partyChanged=false,pcChanged=false;const placements=[];
for(const request of requests){const meta=MON_INDEX.find(m=>m.id===request.species);if(!meta||meta.unavailable||!Number.isInteger(request.level)||request.level<1||request.level>100)throw Error('เลือกชนิดโปเกมอนและเลเวล 1–100');const p=meta.offset+(request.level-1)*76,mon=templates.slice(p,p+76),mv=view(mon);if((mv.getUint16(28,true)&4095)!==(meta.species??meta.id)||((mv.getUint32(28,true)>>>12)&31)!==(meta.form??0)||mon[60]!==request.level||mv.getUint16(64,true)<1)throw Error('แม่แบบโปเกมอนไม่ผ่านการตรวจสอบ');
// Assign full trainer ID, raw OT name and gender from this save. Other packed traits stay intact.
mon.set(out.subarray(s.trainer+10,s.trainer+14),4);mon.set(out.subarray(s.trainer,s.trainer+7),43);mon[50]=(mon[50]&~64)|((out[s.trainer+8]&1)<<6);
if(request.destination==='party'){if(count>=6)throw Error('Party เต็มแล้ว (6 ตัว) เลือก PC แทน');const pos=s.world+0x238+count*76,old=out.subarray(pos,pos+76);if(!old.every((x,i)=>x===0||(i===61&&x===255)))throw Error('ช่องถัดไปของ Party มีข้อมูลอยู่ จึงไม่เขียนทับ');out.set(mon,pos);placements.push({destination:'party',slot:count});count++;partyChanged=true;}else if(request.destination==='pc'){const box=request.box;if(!Number.isInteger(box)||box<0||box>=21)throw Error('เลือกกล่อง PC 1–21');let found=-1;if(request.slot!==undefined){if(!Number.isInteger(request.slot)||request.slot<0||request.slot>=30)throw Error('เลือกช่อง PC 1–30');const pos=4+(box*30+request.slot)*52;if(!storage.subarray(pos,pos+52).every(x=>x===0))throw Error('ช่อง PC นี้มีโปเกมอนอยู่แล้ว');found=request.slot;}for(let slot=0;found<0&&slot<30;slot++){const pos=4+(box*30+slot)*52;if(storage.subarray(pos,pos+52).every(x=>x===0)){found=slot;break;}}if(found<0)throw Error(`PC กล่อง ${box+1} เต็มแล้ว หรือไม่มีช่องว่างที่เขียนได้`);storage.set(mon.subarray(0,52),4+(box*30+found)*52);placements.push({destination:'pc',box,slot:found});pcChanged=true;}else throw Error('เลือกปลายทาง Party หรือ PC');}
if(partyChanged){out[s.world+0x234]=count;v.setUint16(s.world+0xff6,checksum(out,s.world,PROFILE.sizes[1]),true);}if(pcChanged){let offset=0;for(let id=5;id<=13;id++){const n=PROFILE.sizes[id],pos=s.active.sections.get(id),chunk=storage.subarray(offset,offset+n);if(!chunk.every((x,i)=>x===out[pos+i])){out.set(chunk,pos);v.setUint16(pos+0xff6,checksum(out,pos,n),true);}offset+=n;}}parseSave(out);capacity(out);return out;}
